 if(g.art)b.style.setProperty('--thumb',`url("${g.art}")`);
 const num=document.createElement('span');num.textContent=String(i+1).padStart(2,'0');
 const copy=document.createElement('div'),name=document.createElement('b'),credit=document.createElement('small');
