 document.querySelector('.catalogue-showcase').dataset.game=g.name.toLowerCase();
 const art=el('catalogue-art');art.hidden=!g.art;if(g.art){art.src=g.art;art.alt=g.name+' artwork';}
 const logo=el('catalogue-logo'),wordmark=el('catalogue-wordmark');logo.hidden=!g.logo;wordmark.hidden=!!g.logo;
 if(g.logo){logo.src=g.logo;logo.alt=g.name;}else wordmark.textContent=g.name;
