 el('catalogue-description').textContent=g.description;
 const badges=el('catalogue-platforms');badges.replaceChildren();
 (platformMap[g.name]||[]).forEach(key=>{
 const [file,label]=platformAssets[key],badge=document.createElement('span'),img=document.createElement('img'),txt=document.createElement('span');
 img.src=asset('assets/platforms/'+file);img.alt='';txt.textContent=label;badge.append(img,txt);badges.append(badge);
 });
 el('catalogue-link').href=g.url;el('catalogue-link').textContent='Explore '+g.name+' ↗';
 el('catalogue-count').textContent=String(active+1).padStart(2,'0')+' / '+catalogue.length;
